#!/usr/bin/env python3
import base64
from collections import Counter
from itertools import cycle
from rfc8032 import point_add, point_compress, point_decompress, point_equal, point_mul, G, negate

# Known key bytes
known_key = [238, 183, 202, 199, 117]

def topoint(n):
    return point_mul(n, G)

def frompoint(p):
    try:
        return next(filter(lambda x: point_equal(p, topoint(x)), range(256)))
    except StopIteration:
        return None

def decrypt_block(key_byte, enc_block):
    try:
        block_point = point_decompress(base64.b64decode(enc_block))
        dec_point = point_add(negate(topoint(key_byte)), block_point)
        decrypted = frompoint(dec_point)
        return chr(decrypted) if decrypted is not None else None
    except:
        return None

def analyze_blocks(blocks):
    block_stats = []
    for pos, blocks_at_pos in enumerate(zip(*[blocks[i:i+12] for i in range(0, len(blocks), 12)])):
        counter = Counter(blocks_at_pos)
        most_common = counter.most_common()
        repetition_rate = most_common[0][1] / len(blocks_at_pos) if most_common else 0
        block_stats.append({
            'position': pos,
            'total_blocks': len(blocks_at_pos),
            'unique_blocks': len(counter),
            'repetition_rate': repetition_rate,
            'most_common': most_common
        })
    return block_stats

def main():
    # Read ciphertext
    with open('ciphertext', 'rb') as f:
        ciphertext = f.read()

    # Split into blocks
    blocks = ciphertext.strip().split(b';')

    # Decrypt first 5 blocks using known key bytes
    decrypted = []
    for i, key_byte in enumerate(known_key):
        dec = decrypt_block(key_byte, blocks[i])
        if dec:
            decrypted.append(f"Block {i}: {dec} (key={key_byte})")

    # Analyze block statistics
    stats = analyze_blocks(blocks)

    # Focus on position 10 (52% repetition rate)
    pos_10_blocks = blocks[10::12]  # Every 12th block starting at position 10
    counter_10 = Counter(pos_10_blocks)
    most_common_10 = counter_10.most_common()

    # Try common English characters on most frequent blocks
    common_chars = [(' ', 32), ('e', 101), ('t', 116), ('a', 97), ('o', 111), ('i', 105), ('n', 110)]
    test_results = []

    for block, count in most_common_10[:3]:  # Test top 3 most common blocks
        for char, ascii_val in common_chars:
            for key_test in range(256):
                dec = decrypt_block(key_test, block)
                if dec == char:
                    test_results.append(f"Position 10: Block {block[:20]}... could be '{char}' with key={key_test}")

    # Print results
    print("\nDecrypted blocks with known keys:")
    for d in decrypted:
        print(d)

    print("\nPosition 10 analysis:")
    print(f"Total unique blocks: {len(counter_10)}")
    print(f"Most common block count: {most_common_10[0][1]}")
    print(f"Repetition rate: {most_common_10[0][1]/len(pos_10_blocks):.2%}")

    print("\nPossible character matches:")
    for result in test_results:
        print(result)

if __name__ == '__main__':
    main()

