        self.known_key_bytes = {
            0: 238,
            1: 183,
            2: 202,
            3: 199,
            4: 117,
            10: 158
        }
        self.key_points = {pos: point_mul(key, G) for pos, key in self.known_key_bytes.items()}
        self.ascii_points = {}
        self._precompute_ascii_points()

    def _precompute_ascii_points(self):
        """Precompute points for ASCII printable characters"""
        for i in range(32, 127):
            self.ascii_points[point_mul(i, G)] = i

    def decrypt_block(self, ct_block, key_byte):
        """Decrypt a single block using a key byte"""
        try:
            ct_point = point_decompress(base64.b64decode(ct_block))
            key_point = point_mul(key_byte, G)
            neg_key_point = (key_point[0], -key_point[1], -key_point[2], key_point[3])
            dec_point = point_add(ct_point, neg_key_point)
            if dec_point in self.ascii_points:
                return chr(self.ascii_points[dec_point])
        except:
            pass
        return None

    def process_ciphertext(self, ciphertext):
        """Process the entire ciphertext looking for patterns"""
        blocks = ciphertext.strip().split(b';')
        print(f"Processing {len(blocks)} blocks...")

        # Try known key positions
