import base64
from itertools import product
import string

from rfc8032 import point_add, point_compress, point_decompress, point_equal, point_mul, G

KEYLEN = 12

def topoint(n):
    return point_mul(n, G)

def frompoint(p):
    try:
        return next(filter(lambda x: point_equal(p,topoint(x)), range(256)))
    except StopIteration:
        return None

negate = lambda p: (p[0], -p[1], -p[2], p[3])

def decrypt_single(block, key_byte):
    if key_byte is None:
        return None
    target = point_decompress(base64.b64decode(block))
    keypoint = topoint(key_byte)
    pt_point = point_add(negate(keypoint), target)
    pt_val = frompoint(pt_point)
    if pt_val is not None:
        return chr(pt_val)
    return None

def get_key_byte(block, pt_char):
    target = point_decompress(base64.b64decode(block))
    for k in range(256):
        keypoint = topoint(k)
        pt_point = point_add(negate(keypoint), target)
        pt_val = frompoint(pt_point)
        if pt_val is not None and chr(pt_val) == pt_char:
            return k
    return None

def test_key_bytes_in_sequence(blocks, key_start_pos, key_byte_candidates):
    results = []
    for key_byte in key_byte_candidates:
        # Test this key byte at positions key_start_pos + n*KEYLEN
        chars = []
        valid = True
        for block_pos in range(key_start_pos, len(blocks), KEYLEN):
            c = decrypt_single(blocks[block_pos], key_byte)
            if c is None or c not in string.printable:
                valid = False
                break
            chars.append(c)
        if valid and len(chars) > 2:  # At least 3 characters decrypted
            results.append((key_byte, ''.join(chars)))
    return results

def main():
    with open('/home/ctfplayer/ctf_files/ciphertext', 'r') as f:
        blocks = f.read().strip().split(';')

    # First find definite key bytes from known characters
    key = [None] * KEYLEN
    key[0] = get_key_byte(blocks[0], 'f')  # 238
    key[1] = get_key_byte(blocks[1], 'l')  # 183
    key[2] = get_key_byte(blocks[2], 'a')  # 202
    key[3] = get_key_byte(blocks[3], 'g')  # 199
    key[4] = get_key_byte(blocks[4], '{')  # 117
    print("Initial key bytes found:", key[:5])

    # For each key position, find candidates that give printable ASCII in sequence
    for key_pos in range(5, KEYLEN):
        print(f"\nTrying key position {key_pos}:")
        candidates = []
        for k in range(256):
            c = decrypt_single(blocks[key_pos], k)
            if c is not None and c in string.printable:
                candidates.append(k)

        # Test candidates across multiple blocks
        results = test_key_bytes_in_sequence(blocks, key_pos, candidates)

        print(f"Found {len(results)} valid sequences:")
        for key_byte, chars in results:
            print(f"Key byte {key_byte:3d} -> {chars}")
            # If we find a sequence that looks like English text, store it
            if all(c in (string.ascii_lowercase + string.digits + '_{}') for c in chars):
                print(f"Found promising key byte {key_byte}")
                key[key_pos] = key_byte

    print("\nFinal key state:", key)

    # Try to decrypt some blocks with what we have
    flag_parts = []
    for i, block in enumerate(blocks[:50]):  # First 50 blocks should be enough
        key_byte = key[i % KEYLEN]
        if key_byte is None:
            flag_parts.append('?')
        else:
            c = decrypt_single(block, key_byte)
            flag_parts.append(c if c else '?')

