        pt_point = point_add(negate(keypoint), target)
        pt_val = frompoint(pt_point)
        if pt_val is not None and chr(pt_val) == pt_char:
            return k
    return None

def test_key_sequence(blocks, pos, key_byte, expected_pattern):
    chars = []
    for block_pos in range(pos, min(len(blocks), pos + len(expected_pattern) * KEYLEN), KEYLEN):
        c = decrypt_single(blocks[block_pos], key_byte)
        if c is None:
            return False
        chars.append(c)
    decrypted = ''.join(chars)
    return expected_pattern in decrypted

def main():
    with open('/home/ctfplayer/ctf_files/ciphertext', 'r') as f:
        blocks = f.read().strip().split(';')

