    # Expected patterns:
    patterns = [
        ('realizing', 5),  # Starting at position 5
        ('crypto', 20),    # Should appear later
        ('try', 15)        # Appears in the middle
    ]

    for pattern, start_pos in patterns:
        print(f"\nLooking for pattern '{pattern}' starting at position {start_pos}")
        # For each character position in the pattern
        for i, expected_char in enumerate(pattern):
